insert into _seo (slug, description, features, seo, alt) values
  ($j$qeelasee-fast-volume-glue$j$, $j$A very fast lash glue that sets in about 0.1-0.3 seconds, made for volume and mega volume artists who need fans to lock in place the moment they touch the natural lash. The supplier rates retention at 8-9 weeks. Choose the Volume formula or Master Glue 0609, in a 5ml bottle.$j$, $j$["0.1-0.3s drying time", "For volume and mega volume", "Retention 8-9 weeks (supplier)", "5ml, Volume or Master 0609"]$j$::jsonb, $j${"title": "Fast Volume Lash Glue 0.1-0.3s Dry, 5ml | Kenya", "meta": "Very fast 0.1-0.3s lash glue for volume and mega volume fans, 8-9 weeks retention (supplier), 5ml. Volume or Master 0609 formula. Kenya.", "keyword": "fast volume lash glue", "keywords": ["0.1 second lash glue", "volume lash adhesive", "master lash glue", "fast drying eyelash glue", "lash glue Kenya", "eyelash extension glue price in Kenya"], "alt": "Black bottle of fast volume eyelash glue with gold label", "sections": [{"heading": "Who it suits", "body": "Experienced volume artists who place fans quickly. If you still need time to adjust each lash, choose one of our 0.5s or 1s glues instead."}, {"heading": "Choosing a drying speed", "body": "The faster a glue dries, the less time you have to place and adjust each lash, so very fast glues suit experienced volume artists and slower glues suit beginners and classic work. Humidity changes drying speed too: lash glue sets faster in humid air and slower in dry air, which is why many artists in Nairobi keep two glues for the dry and rainy seasons."}, {"heading": "Storing your glue", "body": "Keep the bottle tightly closed in a cool, dry place; the supplier recommends 3-7°C, such as a fridge, for unopened bottles. Take it out about 20 minutes before use so it reaches room temperature, shake well, and wipe the nozzle clean before closing. Unopened glue keeps about a year; once opened, use it within 1-3 months for the best bond."}, {"heading": "Ordering from Lashtribe Africa", "body": "Lashtribe Africa is a preorder wholesale shop for lash technicians in Kenya. Your order joins the next supplier shipping batch, which leaves around the middle and the end of every month, so you pay close to source prices instead of local shelf prices.\n\nBuy the minimum quantity shown on this page to get the wholesale price; smaller orders pay the retail price. Pay by M-Pesa or card. Shipping to our office is worked out by weight at checkout, and we contact you as soon as your batch lands to arrange delivery to your salon."}], "specs": [{"label": "Drying time", "value": "0.1-0.3 seconds"}, {"label": "Retention", "value": "8-9 weeks (supplier)"}, {"label": "Volume", "value": "5ml"}, {"label": "Formulas", "value": "Volume lash glue, Master glue 0609"}, {"label": "Colour", "value": "Black"}, {"label": "Shelf life", "value": "1 year unopened, 1-3 months after opening"}], "faqs": [{"q": "Where can I buy fast volume lash glue in Kenya?", "a": "Order fast volume lash glue here on Lashtribe Africa. Add it to your cart, pay by M-Pesa or card, and it ships with the next supplier batch to our office in Kenya. We contact you when it arrives to arrange delivery to your salon or home."}, {"q": "How much is fast volume lash glue in Kenya?", "a": "The price on this page is the live price. Order the minimum quantity for the wholesale price; smaller orders pay the retail price. Shipping is added by weight at checkout, so you see the full cost before you pay."}, {"q": "Is it safe for sensitive eyes?", "a": "Lash glue contains cyanoacrylate and gives off fumes while it cures. The supplier recommends it for clients without sensitive skin. Do a patch test with new clients, keep the client's eyes closed and use a fan to clear fumes."}]}$j$::jsonb, $j$Black bottle of fast volume eyelash glue with gold label$j$),
  ($j$qeelasee-fast-drying-glue-05s$j$, $j$An all-round fast drying eyelash extension glue that sets in about 0.5 seconds: quick enough for volume fans but still workable for classic and hybrid sets. The supplier rates retention at 7-8 weeks. 5ml bottle.$j$, $j$["0.5s drying time", "Classic, hybrid and volume", "Retention 7-8 weeks (supplier)", "5ml bottle"]$j$::jsonb, $j${"title": "0.5s Fast Drying Eyelash Extension Glue 5ml | Kenya", "meta": "0.5 second fast drying eyelash extension glue for classic, hybrid and volume sets, 7-8 weeks retention (supplier), 5ml. Wholesale lash glue Kenya.", "keyword": "fast drying eyelash glue", "keywords": ["fast drying eyelash glue", "0.5s lash adhesive", "eyelash extension glue", "black lash glue", "lash glue Kenya", "eyelash extension glue price in Kenya"], "alt": "Bottle of 0.5 second fast drying eyelash extension glue with purple cap", "sections": [{"heading": "Who it suits", "body": "Intermediate and experienced artists who want one glue for most sets."}, {"heading": "Choosing a drying speed", "body": "The faster a glue dries, the less time you have to place and adjust each lash, so very fast glues suit experienced volume artists and slower glues suit beginners and classic work. Humidity changes drying speed too: lash glue sets faster in humid air and slower in dry air, which is why many artists in Nairobi keep two glues for the dry and rainy seasons."}, {"heading": "Storing your glue", "body": "Keep the bottle tightly closed in a cool, dry place; the supplier recommends 3-7°C, such as a fridge, for unopened bottles. Take it out about 20 minutes before use so it reaches room temperature, shake well, and wipe the nozzle clean before closing. Unopened glue keeps about a year; once opened, use it within 1-3 months for the best bond."}, {"heading": "Ordering from Lashtribe Africa", "body": "Lashtribe Africa is a preorder wholesale shop for lash technicians in Kenya. Your order joins the next supplier shipping batch, which leaves 