-- 0045_product_seo.sql
-- SEO copy for every product (researched 2026-10-30 from supplier pages, the product photos and Kenyan marketplaces).
-- Run in the Supabase SQL editor. Safe to re-run. Needs nothing newer than 0001: it only adds one column.
--
--   * products.seo (jsonb): page title, meta description, keyword(s), sections, specs, FAQs and photo alt text.
--     The product page reads it (src/data/ecommerce-products.js); before this runs the page just shows the description.
--   * products.description becomes the SEO intro paragraph (it is also the 2-line text on product cards).
--   * products.features is filled only where it is still empty (the bullets under the product name).
--   * The first photo's alt text is set. Name, slug, price, options, status and photos are NOT touched.
--   * Products that do not exist are skipped. Review notes and questions: SEO-REVIEW.md in the repo root.

alter table public.products add column if not exists seo jsonb;

create temp table _seo (slug text primary key, description text, features jsonb, seo jsonb, alt text) on commit drop;

update public.products p
   set description = s.description,
       seo = s.seo,
       features = case when p.features is null or jsonb_typeof(p.features) <> 'array' or jsonb_array_length(p.features) = 0
                       then s.features else p.features end,
       images = case when jsonb_typeof(p.images) = 'array' and jsonb_array_length(p.images) > 0
                     then jsonb_set(p.images, '{0,alt}', to_jsonb(s.alt)) else p.images end,
       updated_at = now()
  from _seo s
 where p.slug = s.slug;

-- What changed (and anything live that still has no SEO copy):
select p.status, p.slug, p.name, (p.seo is not null) as has_seo
  from public.products p
 order by (p.seo is not null), p.status, p.name;
